// =====================================================================
// Port of `zcurses_colorget(const char *nam, char *colorpair)` from `Src/Modules/curses.c:331`.
// =====================================================================

/// Port of `zcurses_colorget(const char *nam, char *colorpair)` from `Src/Modules/curses.c:331`.
///
/// Resolve `"fg/bg"` to a color-pair index, allocating a new pair
/// via `init_pair()` semantics (incrementing `next_cp`) on first
/// use. C uses libncurses's `init_pair`; Rust port stores the
/// mapping in the `zcurses_colorpairs` HashMap for later SGR.
pub(crate) fn colorpair_get_or_alloc(spec: &str) -> i32 {
    let mut pairs = colorpairs_lock().lock().unwrap();
    if let Some(&n) = pairs.get(spec) {
        return n as i32;
    }
    let slash = match spec.find('/') {
        Some(p) => p,
        None => return -1,
    };
    let fg = &spec[..slash];
    let bg = &spec[slash + 1..];
    let _fg_n = zcurses_color(fg);
    let _bg_n = zcurses_color(bg);
    if _fg_n == -2 || _bg_n == -2 {
        return -1;
    }
    let mut np = next_cp_lock().lock().unwrap();
    *np = np.saturating_add(1);
    let cp = *np;
    pairs.insert(spec.to_string(), cp);
    cp as i32
}

// =====================================================================
// Keypad / keyboard input helpers — substitutes for libncurses's
// `wgetch` / `wget_wch` + `keypad()` table from `curses_keys.h`.
// =====================================================================

// WARNING: NOT IN CURSES.C — Rust-only termios+read shim. C uses
// libncurses's `wget_wch(w->win, &wi)` / `wgetch(w->win, ...)`.
// Without libncurses linked, the Rust port reads raw bytes from
// stdin (cbreak set by `zccmd_init`) and parses CSI / SS3 sequences
// for arrow + function-key codes. Returns `(string, keycode)`.
// `keycode == 0` means a regular character; non-zero means a
// keypad code.
/// WARNING: NOT IN CURSES.C — Rust-side TTY key-sequence reader; C uses `wgetch()` from libncurses
/// (equivalent C logic at Src/Modules/curses.c:1473).
fn read_key_sequence(want_keypad: bool, _timeout_ms: i32) -> Option<(String, i32)> {
    #[cfg(unix)]
    {
        let mut buf = [0u8; 1];
        let n = io::stdin().read(&mut buf).ok()?;
        if n == 0 {
            return None;
        }
        let c = buf[0];
        if c == 0x1b && want_keypad {
            // CSI / SS3 prefix — read up to a few more bytes.
            let mut seq = vec![c];
            for _ in 0..6 {
                let mut next = [0u8; 1];
                if io::stdin().read(&mut next).ok()? == 0 {
                    break;
                }
                seq.push(next[0]);
                // Final byte for CSI is in 0x40..=0x7E; for ESC O
                // (SS3) it's a single trailing letter.
                if seq.len() >= 3 && (seq[2] >= 0x40 && seq[2] <= 0x7e) {
                    break;
                }
                if seq.len() >= 4 && seq[seq.len() - 1] >= 0x40 && seq[seq.len() - 1] <= 0x7e {
                    break;
                }
            }
            if let Some(code) = csi_to_keypad(&seq) {
                return Some((String::new(), code));
            }
        }
        Some(((c as char).to_string(), 0))
    }
    #[cfg(not(unix))]
    {
        let _ = (want_keypad, _timeout_ms);
        None
    }
}

// WARNING: NOT IN CURSES.C — table-driven CSI/SS3 → libncurses
// keypad-code mapping. Substitutes for the `curses_keys.h`
// autogenerated table that ncurses' `keypad()` uses internally.
// Values match libncurses constants (KEY_UP = 0o403, etc.).
fn csi_to_keypad(seq: &[u8]) -> Option<i32> {
    if seq.len() < 3 || seq[0] != 0x1b {
        return None;
    }
    if seq[1] == b'[' {
        match seq[2] {
            b'A' => Some(KEY_UP),
            b'B' => Some(KEY_DOWN),
            b'C' => Some(KEY_RIGHT),
            b'D' => Some(KEY_LEFT),
            b'H' => Some(KEY_HOME),
            b'F' => Some(KEY_END),
            b'1' if seq.len() >= 4 && seq[3] == b'~' => Some(KEY_HOME),
            b'2' if seq.len() >= 4 && seq[3] == b'~' => Some(KEY_IC),
            b'3' if seq.len() >= 4 && seq[3] == b'~' => Some(KEY_DC),
            b'4' if seq.len() >= 4 && seq[3] == b'~' => Some(KEY_END),
            b'5' if seq.len() >= 4 && seq[3] == b'~' => Some(KEY_PPAGE),
            b'6' if seq.len() >= 4 && seq[3] == b'~' => Some(KEY_NPAGE),
            _ => None,
        }
    } else if seq[1] == b'O' {
        match seq[2] {
            b'A' => Some(KEY_UP),
            b'B' => Some(KEY_DOWN),
            b'C' => Some(KEY_RIGHT),
            b'D' => Some(KEY_LEFT),
            b'P' => Some(KEY_F0 + 1),
            b'Q' => Some(KEY_F0 + 2),
            b'R' => Some(KEY_F0 + 3),
            b'S' => Some(KEY_F0 + 4),
            _ => None,
        }
    } else {
        None
    }
}

// WARNING: NOT IN CURSES.C — Rust-only reverse lookup of the
// keypad-code → name table. C uses `keypad_names[]` from
// `curses_keys.h`; Rust port hardcodes the most common keys to
// keep the table compact.
fn keypad_name(code: i32) -> Option<String> {
    // Direct value-to-name table mirroring what C's awk-generated
    // keypad_names[] in curses_keys.h carries — every KEY_* define
    // from the system curses.h except MIN, MAX, CODE_YES (per the
    // awk filter at curses_keys.awk:8). Values match the canonical
    // ncurses octal-coded ranges:
    //   0o401-0o407: base set (BREAK..BACKSPACE)
    //   0o410-0o467: F-keys (F0..F63, handled inline below)
    //   0o510+:      extended set (DL..MOUSE)
    // Octal literals match the curses.h #defines exactly so a side-
    // by-side review against the original macros stays trivially
    // verifiable.
    let name = match code {
        // c:base set
        0o401 => "BREAK",
        KEY_DOWN => "DOWN",     // 0o402
        KEY_UP => "UP",         // 0o403
        KEY_LEFT => "LEFT",     // 0o404
        KEY_RIGHT => "RIGHT",   // 0o405
        KEY_HOME => "HOME",     // 0o406
        0o407 => "BACKSPACE",
        // c:extended set
        0o510 => "DL",
        0o511 => "IL",
        KEY_DC => "DC",         // 0o512
        KEY_IC => "IC",         // 0o513
        0o514 => "EIC",
        0o515 => "CLEAR",
        0o516 => "EOS",
        0o517 => "EOL",
        0o520 => "SF",
        0o521 => "SR",
        KEY_NPAGE => "NPAGE",   // 0o522
        KEY_PPAGE => "PPAGE",   // 0o523
        0o524 => "STAB",
        0o525 => "CTAB",
        0o526 => "CATAB",
        0o527 => "ENTER",
        0o530 => "SRESET",
        0o531 => "RESET",
        0o532 => "PRINT",
        0o533 => "LL",
        0o534 => "A1",
        0o535 => "A3",
        0o536 => "B2",
        0o537 => "C1",
        0o540 => "C3",
        0o541 => "BTAB",
        0o542 => "BEG",
        0o543 => "CANCEL",
        0o544 => "CLOSE",
        0o545 => "COMMAND",
        0o546 => "COPY",
        0o547 => "CREATE",
        KEY_END => "END",       // 0o550
        0o551 => "EXIT",
        0o552 => "FIND",
        0o553 => "HELP",
        0o554 => "MARK",
        0o555 => "MESSAGE",
        0o556 => "MOVE",
        0o557 => "NEXT",
        0o560 => "OPEN",
        0o561 => "OPTIONS",
        0o562 => "PREVIOUS",
        0o563 => "REDO",
        0o564 => "REFERENCE",
        0o565 => "REFRESH",
        0o566 => "REPLACE",
        0o567 => "RESTART",
        0o570 => "RESUME",
        0o571 => "SAVE",
        0o572 => "SBEG",
        0o573 => "SCANCEL",
        0o574 => "SCOMMAND",
        0o575 => "SCOPY",
        0o576 => "SCREATE",
        0o577 => "SDC",
        0o600 => "SDL",
        0o601 => "SELECT",
        0o602 => "SEND",
        0o603 => "SEOL",
        0o604 => "SEXIT",
        0o605 => "SFIND",
        0o606 => "SHELP",
        0o607 => "SHOME",
        0o610 => "SIC",
        0o611 => "SLEFT",
        0o612 => "SMESSAGE",
        0o613 => "SMOVE",
        0o614 => "SNEXT",
        0o615 => "SOPTIONS",
        0o616 => "SPREVIOUS",
        0o617 => "SPRINT",
        0o620 => "SREDO",
        0o621 => "SREPLACE",
        0o622 => "SRIGHT",
        0o623 => "SRSUME",
        0o624 => "SSAVE",
        0o625 => "SSUSPEND",
        0o626 => "SUNDO",
        0o627 => "SUSPEND",
        0o630 => "UNDO",
        0o631 => "MOUSE",
        0o632 => "RESIZE",
        0o633 => "EVENT", // KEY_EVENT — may not be defined on all platforms
        // F-keys: F0..F63 at KEY_F0 + n.
        c if c >= KEY_F0 && c < KEY_F0 + 64 => {
            return Some(format!("F{}", c - KEY_F0));
        }
        _ => return None,
    };
    Some(name.to_string())
}

